(() => {'use strict';const g=()=>window.gameDebug,$=id=>document.getElementById(id);
function locked(item){const a=g().active();if(g().busy||window.HUD?.pending||g().state.combat)return 'Дождитесь окончания движения или боя.';if(item.id.startsWith('gear')){const name=a.inventory[+item.id.slice(4)]||'';if(InventoryRules.armorName(name)&&a.armorEquipped!==false)return 'Сначала снимите броню.';const hand=InventoryRules.handType(name);if(hand&&a.hands.includes(hand))return 'Сначала уберите этот предмет из рук.';return '';}if(item.id==='torch'){if(!a.torches)return 'Нет факелов.';if(a.hands.includes('torch')&&a.torches===1)return 'Сначала погасите и уберите факел.';return '';}if(item.id==='potion')return g().state.potions>0?'':'Нет зелий.';return 'Этот предмет связан с историей или не передаётся.';}
function take(item){if(locked(item))return null;const a=g().active();if(item.id.startsWith('gear')){const index=+item.id.slice(4);const name=a.inventory.splice(index,1)[0];return name?{name,itemType:'gear'}:null;}if(item.id==='torch'){a.torches--;return{name:'Факел',itemType:'torch'};}if(item.id==='potion'){g().state.potions--;return{name:'Лечебное зелье',itemType:'potion'};}return null;}
function drop(item){const reason=locked(item);if(reason){g().tell(reason);g().render();return;}if((g().state.drops||[]).length>=100){g().tell("Сначала подберите оставленные вещи.");g().render();return;}const a=g().active(),S=g().scene,candidates=[];for(let y=0;y<S.H;y++)for(let x=0;x<S.W;x++)if(!g().blocked({x,y})&&!g().props.some(p=>p.x===x&&p.y===y)&&!g().all().some(p=>p.x===x&&p.y===y)){const distance=Math.abs(x-a.x)+Math.abs(y-a.y);if(distance<=2)candidates.push({x,y,distance});}candidates.sort((a,b)=>a.distance-b.distance||a.y-b.y||a.x-b.x);if(!candidates.length){g().tell('Рядом нет свободной клетки для вещи.');g().render();return;}const data=take(item);if(!data)return;g().state.drops||=[];g().state.drops.push({...data,id:'drop-'+crypto.randomUUID(),scene:S.id,x:candidates[0].x,y:candidates[0].y});g().tell('Вы оставили «'+data.name+'» на полу. Вещь можно подобрать обратно.');g().save();g().render();}
function roomFor(type,name){return InventoryRules.canAdd(g().active(),g().state,type,name);}
function pickup(p){const drops=g().state.drops||[],i=drops.findIndex(d=>d.id===p.id);if(i<0)return;const d=drops[i];if(!roomFor(d.itemType,d.name)){window.openObjectDialogue({name:'Рюкзак заполнен',description:'Все 20 ячеек заняты. Освободите место или передайте вещь NPC. Предмет остался на полу.'});g().render();return;}if(d.itemType==='gear')g().active().inventory.push(d.name);else if(d.itemType==='torch')g().active().torches++;else if(d.itemType==='potion')g().state.potions++;drops.splice(i,1);g().tell('Подобрано: '+d.name+'.');g().save();g().render();}
function transfer(item){if(locked(item))return;const d=$('modal'),body=$('modal-body');$('modal-title').textContent='Передать предмет';body.replaceChildren();const npcs=g().props.filter(p=>p.type==='npc');if(!npcs.length){body.textContent='В этой комнате нет NPC. Подойдите в комнату с персонажем.';}for(const npc of npcs){const b=document.createElement('button');b.className='npc-transfer';const portrait=npc.npc?Characters.portrait(5,{gen:npc.npc}):window.Artwork.npc(npc.name);const text=document.createElement('span');text.textContent=npc.name;b.append(portrait,text);b.onclick=async()=>{d.close();window.viewsDebug.switchTab('map');const ok=await g().approachTransfer(npc,()=>{const data=take(item);if(!data)return;g().state.npcGifts||=[];g().state.npcGifts.push(npc.id+': '+data.name);if(g().state.npcGifts.length>200)g().state.npcGifts.shift();g().tell('Вы передали «'+data.name+'» персонажу '+npc.name+'.');window.episodeDialogue('Спасибо, я сохраню эту вещь.',[{label:'Вернуться к карте',fn:window.closeDialogue}],npc.name,true);});if(!ok){g().tell('Передача отменена: нет свободного прохода или движение остановлено.');g().render();}};body.append(b);}d.showModal();}
function unequip(item){const a=g().active();if(g().busy||g().state.combat||window.HUD?.pending)return;const name=a.inventory[+item.id.slice(4)];if(!name)return;const copy={...a,hands:[...a.hands],inventory:[...a.inventory]};if(InventoryRules.armorName(name))copy.armorEquipped=false;else{const hand=item.id==='torch'?'torch':InventoryRules.handType(name);copy.hands=copy.hands.map(h=>h===hand?'empty':h);}if(InventoryRules.slotsUsed(copy,g().state)>20){window.openObjectDialogue({name:'Нет места для снаряжения',description:'Освободите ячейку в рюкзаке, чтобы снять этот предмет.'});return;}if(InventoryRules.armorName(name)){a.armorEquipped=false;a.armorAC=10+DND.mod(a.stats.dex);}else{a.hands=copy.hands;if(!a.hands.includes('torch'))a.torch=false;}window.Torches.ensure();a.baseAC=a.ac;g().save();g().render();}
function wear(item){const a=g().active(),name=a.inventory[+item.id.slice(4)];if(g().busy||g().state.combat||!InventoryRules.armorName(name))return;const kit=HeroRules.CLASSES[a.classId]?.kits[a.kit];if(!kit)return;a.armorEquipped=true;a.armorAC=kit.ac+(a.classId==='fighter'?0:a.classId==='cleric'?Math.min(2,DND.mod(a.stats.dex)):DND.mod(a.stats.dex));window.Torches.ensure();a.baseAC=a.ac;g().save();g().render();}
function controls(item,host){if(!item.id.startsWith('gear')&&!['torch','potion'].includes(item.id))return;const reason=locked(item),a=g().active(),name=item.id.startsWith('gear')?a.inventory[+item.id.slice(4)]:'';if(item.id.startsWith('gear')&&(reason.startsWith('Сначала')||InventoryRules.armorName(name))){const b=document.createElement('button');b.textContent=InventoryRules.armorName(name)&&a.armorEquipped===false?'Надеть броню':'Снять в рюкзак';b.onclick=()=>InventoryRules.armorName(name)&&a.armorEquipped===false?wear(item):unequip(item);b.disabled=g().busy||g().state.combat;window.UIIcons.apply(b,'armor');host.append(b);}for(const [text,fn,icon]of [['Выбросить',()=>drop(item),'drop'],['Передать NPC',()=>transfer(item),'transfer']]){const b=document.createElement('button');b.className='inventory-action';b.textContent=text;b.disabled=!!reason;b.onclick=fn;window.UIIcons.apply(b,icon);host.append(b);}if(reason){const p=document.createElement('p');p.className='item-lock-note';p.textContent=reason;host.append(p);}}
window.Inventory={drop,pickup,transfer,controls,locked,unequip,wear,roomFor};})();
